-- Modify "notification_address" table
ALTER TABLE "identity"."notification_address" ADD CONSTRAINT "notification_address_proof_check" CHECK ((state <> 'pending'::text) OR ((proof_hash IS NOT NULL) AND (proof_expires_at IS NOT NULL))), ADD COLUMN "proof_hash" text NULL, ADD COLUMN "proof_expires_at" timestamptz NULL, ADD COLUMN "proof_attempts" integer NOT NULL DEFAULT 0;
-- Modify "security_notification" table
ALTER TABLE "identity"."security_notification" DROP CONSTRAINT "security_notification_event_check", ADD CONSTRAINT "security_notification_event_check" CHECK (event = ANY (ARRAY['authenticator_bound'::text, 'authenticator_removed'::text, 'recovery_codes_issued'::text, 'account_recovered'::text, 'notification_address_changed'::text, 'notification_address_proof'::text])), ADD CONSTRAINT "security_notification_secret_check" CHECK ((sealed_secret IS NULL) OR ((event = 'notification_address_proof'::text) AND (state = 'requested'::text))), ADD COLUMN "sealed_secret" text NULL; -- atlas:destructive-approved: widening a CHECK, reviewed 2026-10-07
